import React, { useState } from 'react';
import { beesAlert } from './utils/emptyIllustration';
import { Image, Container, Overlay, ErrorIllustration } from './Image.styles';
import { ImageTypes } from './Image.type';

const ImageComponent = ({
  containerCss,
  src,
  aspectRatio = 4 / 3,
  variant = 'fill',
  position,
  isInteractive = false,
  disabled = false,
  customErrorImage,
  ...props
}: ImageTypes): JSX.Element => {
  const [hasError, setHasError] = useState<boolean>(false);
  const [hasCustomImageError, setHasCustomImageError] = useState<boolean>(false);

  if (hasError) {
    const { width, height } = props;
    return (
      <ErrorIllustration css={containerCss}>
        {!hasCustomImageError && customErrorImage ? (
          <img
            src={customErrorImage?.src}
            alt={customErrorImage?.alt}
            width={width}
            height={height}
            onError={() => {
              // eslint-disable-next-line no-console
              console.warn(
                "The custom image provided wasn't able to load, the default image will be used instead."
              );
              setHasCustomImageError(true);
            }}
            {...props}
          />
        ) : (
          <img src={beesAlert.src} alt={beesAlert.alt} width={width} height={height} {...props} />
        )}
      </ErrorIllustration>
    );
  }

  return (
    <Container css={containerCss}>
      <Image
        src={src}
        css={{ aspectRatio, objectPosition: position }}
        variant={variant}
        {...props}
        onError={() => setHasError(true)}
      />
      {isInteractive && <Overlay isDisabled={disabled} />}
    </Container>
  );
};

export default ImageComponent;
